insert into public.performer_descriptions (slug, description, updated_at)
values
  ('alyx-star', 'Alyx Star has more than thirty videos on VEXN, from 6-minute clips to 57-minute scenes, and about half run over 30 minutes. [Brunette](/category/brunette) and [Big Tits](/category/big-tits) tag most of them, with smaller groups tagged [Lesbian](/category/lesbian), [Homemade](/category/homemade) and [Hardcore](/category/hardcore), and several short girl-girl scenes come from [New Sensations](/channel/new-sensations). The longest are a 57-minute [threesome](/category/threesome) with Skylar Snow and a 56-minute scene titled Her All Natural Triple Ds. Every video plays from its source site.', now()),
  ('angela-white', 'Angela White has more than forty videos on VEXN, and about seven in ten run 30 minutes or more. [Big Tits](/category/big-tits) and [Hardcore](/category/hardcore) are the most common tags, with [Romantic](/category/romantic) on a good share, and several come from the [Brazzers](/channel/brazzers), [Adult Time](/channel/adult-time) and [Nuru Massage](/channel/nuru-massage) channels. Frequent co-stars include [Manuel Ferrara](/actor/manuel-ferrara), [Ricky Johnson](/actor/ricky-johnson) and [Seth Gamble](/actor/seth-gamble). The longest is the 107-minute Manuel Doesn''t Forgive The Foxes. Every video plays from its source site.', now()),
  ('bharti-jha', 'Bharti Jha is a recurring performer in the [Indian](/category/indian) amateur videos on VEXN, with scenes ranging from short [homemade](/category/homemade) clips to a longer casting-themed feature, most tagged [Big Tits](/category/big-tits) and [MILF](/category/milf). More videos like these are in the [Desi](/category/desi) category. Every video plays from its source site.', now()),
  ('blake-blossom', 'Blake Blossom has about thirty videos on VEXN, and most run over half an hour, up to 50 minutes. [Blonde](/category/blonde) is the most common tag, with [Big Tits](/category/big-tits), [Hardcore](/category/hardcore), [Big Ass](/category/big-ass) and [Lesbian](/category/lesbian) next, and two scenes come from [Vixen](/channel/vixen). The longest are a 50-minute lesbian [massage](/category/massage) with Leana Lovings and a 50-minute [interracial](/category/interracial) scene, and Sage Roux co-stars in one of the [public](/category/public) scenes. Every video plays from its source site.', now()),
  ('brandi-love', 'Brandi Love appears in VEXN scenes ranging from [Nuru Massage](/channel/nuru-massage) to [POV](/category/pov) [MILF](/category/milf) features, drawn from a long-running pornstar catalogue. Every video plays from its source site.', now()),
  ('dani-daniels', 'Dani Daniels has more than thirty videos on VEXN. [Brunette](/category/brunette) and [Lesbian](/category/lesbian) are the most common tags, followed by [Big Ass](/category/big-ass) and [Masturbation](/category/masturbation), and [Karla Kush](/actor/karla-kush) co-stars in several girl-girl scenes, two of them from [New Sensations](/channel/new-sensations). Runtimes run from 8 to 48 minutes: the longest is a 48-minute lesbian [striptease](/category/striptease) with Karlie Montana, and a couple are [public](/category/public) scenes. Every video plays from its source site.', now()),
  ('dee-williams', 'Dee Williams stars in VEXN scenes spanning [Nuru Massage](/channel/nuru-massage), [POV](/category/pov) and [group sex](/category/group-sex) formats, most tagged [Big Tits](/category/big-tits) and [MILF](/category/milf). Every video plays from its source site.', now()),
  ('johnny-sins', 'Johnny Sins appears across the scenes on VEXN, usually opposite a rotating cast of pornstar co-stars in straightforward [hardcore](/category/hardcore) pairings, including two [Vixen](/channel/vixen) scenes. Every video plays from its source site.', now()),
  ('kendra-sunderland', 'Nearly every Kendra Sunderland video on VEXN is a long one: they run between 27 and 61 minutes and almost all are 30 minutes or more. [Blonde](/category/blonde) and [Big Tits](/category/big-tits) are the most common tags, and many are [group sex](/category/group-sex) scenes. [Alina Lopez](/actor/alina-lopez) co-stars in three and [Seth Gamble](/actor/seth-gamble) in two. The longest are a 61-minute scene with four other performers and a 60-minute [interracial](/category/interracial) group scene with Jade Nile. Every video plays from its source site.', now()),
  ('lana-rhoades', 'Lana Rhoades has nearly forty videos on VEXN, and roughly seven in ten run 30 minutes or more. Two are feature-length: a 164-minute [lesbian](/category/lesbian) feature and a title called A New Level of Beauty that runs over 140 minutes. [Brunette](/category/brunette), [Big Tits](/category/big-tits) and [Masturbation](/category/masturbation) are the most common tags, and many are [anal](/category/anal) scenes. [Markus Dupree](/actor/markus-dupree) and [Adriana Chechik](/actor/adriana-chechik) are the most frequent co-stars. Every video plays from its source site.', now()),
  ('lauren-phillips', 'Lauren Phillips has more than thirty videos on VEXN, most of them over half an hour. [Big Tits](/category/big-tits) and [MILF](/category/milf) are the most common tags, with [Redhead](/category/redhead) and [Big Ass](/category/big-ass) close behind. The longest is a 126-minute 2025 feature titled Sperm Bank Overload, followed by a 72-minute scene. [Lena Paul](/actor/lena-paul) co-stars in one scene, and several are [interracial](/category/interracial). Every video plays from its source site.', now()),
  ('lena-paul', 'Lena Paul has more than twenty videos on VEXN, and most are long, with an average of about 47 minutes. [Big Tits](/category/big-tits) and [Hardcore](/category/hardcore) are the most common tags, with some [group sex](/category/group-sex) and [threesome](/category/threesome) titles, and two come from [Adult Time](/channel/adult-time). The longest are two 93-minute titles, My Hot Girlfriend and How I Met My Girlfriend, and [Lauren Phillips](/actor/lauren-phillips) co-stars in one scene. Every video plays from its source site.', now()),
  ('nina-elle', 'Nina Elle appears on VEXN in a [massage](/category/massage) scene from the [Nuru Massage](/channel/nuru-massage) channel. This page lists every video with the performer.', now()),
  ('paola-hard', 'Paola Hard headlines scenes on VEXN, most drawn from ensemble European productions: [group sex](/category/group-sex) scenes, [double penetration](/category/double-penetration) features and pairings with recurring co-stars like Vince Karter and Zlata Shine. Every video plays from its source site.', now()),
  ('payton-preslee', 'Payton Preslee stars in scenes on VEXN, most from the [Nuru Massage](/channel/nuru-massage) channel, spanning [shower](/category/shower), [PAWG](/category/pawg) and [hardcore](/category/hardcore) formats. Every video plays from its source site.', now()),
  ('xander-corvus', 'Xander Corvus appears in VEXN scenes, usually as a co-star in [group sex](/category/group-sex) and swinger themed features, with one scene from [Reality Kings](/channel/reality-kings). This page lists every video with the performer.', now()),
  ('romi-rain', 'Romi Rain has more than fifteen videos on VEXN, most of them half an hour or longer and one running past 100 minutes. Nearly all are tagged [MILF](/category/milf), [big tits](/category/big-tits) and [brunette](/category/brunette), and several are [lesbian](/category/lesbian) scenes.

Romi Rain also appears on the [Adult Time](/channel/adult-time) and [New Sensations](/channel/new-sensations) channels, and the co-stars include [Angela White](/actor/angela-white), [Blake Blossom](/actor/blake-blossom) and Codey Steele, who is in two of the scenes. Every video plays from its source site.', now()),
  ('ava-addams', 'Ava Addams has about a dozen videos on VEXN, from short clips to a 73-minute feature, and almost all are tagged [MILF](/category/milf), [big tits](/category/big-tits) and [brunette](/category/brunette). Several are [anal](/category/anal) scenes, and [big dick](/category/big-dick) is another common tag.

Ava Addams scenes also appear on the [Brazzers](/channel/brazzers) and [Naughty America](/channel/naughty-america) channels, and Kayla Kayden and Brick Danger each co-star twice. Every video plays from its source site.', now()),
  ('comatozze', 'Comatozze is credited on a set of amateur, homemade videos on VEXN, 8 to 22 minutes each. All are tagged [amateur](/category/amateur) and [homemade](/category/homemade), many are filmed [POV](/category/pov), and [big dick](/category/big-dick) and [blonde](/category/blonde) are other common tags; Russian Baddie appears in two. Nearly all sit in the [Comatozze channel](/channel/comatozze). Every video plays from its source site.', now()),
  ('crazy-alisha', 'Crazy Alisha has about ten videos on VEXN, most of them around half an hour. [Big tits](/category/big-tits) tag almost all of them, and many are [anal](/category/anal) scenes with a [cumshot](/category/cumshot) finish; [big ass](/category/big-ass) and [blonde](/category/blonde) are common too. Asya Murkovski co-stars in several, and one scene is on the [Nuru Massage](/channel/nuru-massage) channel. Every video plays from its source site.', now()),
  ('seth-gamble', 'Seth Gamble videos on VEXN run from 22 minutes to a 139-minute feature, and several are [Nuru Massage](/channel/nuru-massage) scenes, with one more on [Adult Time](/channel/adult-time). Co-stars include [Kendra Sunderland](/actor/kendra-sunderland) and [Angela White](/actor/angela-white), twice each, plus [Blake Blossom](/actor/blake-blossom), [Chanel Preston](/actor/chanel-preston) and [Alina Lopez](/actor/alina-lopez). [Big tits](/category/big-tits), [massage](/category/massage) and [hardcore](/category/hardcore) are the most common tags. Every video plays from its source site.', now()),
  ('markus-dupree', 'Markus Dupree videos on VEXN are long, from 29 to 58 minutes. Most co-star [Lana Rhoades](/actor/lana-rhoades), and [Adriana Chechik](/actor/adriana-chechik) and [Angela White](/actor/angela-white) appear twice each. [Anal](/category/anal) is the most common tag, with [threesome](/category/threesome) and [hardcore](/category/hardcore) scenes as well. Every video plays from its source site.', now()),
  ('manuel-ferrara', 'Manuel Ferrara videos on VEXN are long: the shortest runs 31 minutes and the longest is a 164-minute feature. [Angela White](/actor/angela-white) co-stars in three, [Lana Rhoades](/actor/lana-rhoades) in two, and one scene is from [Vixen](/channel/vixen). [Big tits](/category/big-tits), [big ass](/category/big-ass) and [hardcore](/category/hardcore) are the most common tags. Every video plays from its source site.', now()),
  ('jennifer-white', 'Jennifer White has videos on VEXN from an 11-minute clip to a 129-minute feature, most of them tagged [brunette](/category/brunette), with [hardcore](/category/hardcore), [group sex](/category/group-sex) and [MILF](/category/milf) scenes among them. They come from several studios: [Brazzers](/channel/brazzers), [Adult Time](/channel/adult-time) and [Reality Kings](/channel/reality-kings) each have one, and [Blake Blossom](/actor/blake-blossom) co-stars in one scene. Every video plays from its source site.', now()),
  ('chanel-preston', 'Chanel Preston videos on VEXN run from 16 minutes to a 167-minute feature, and many are [MILF](/category/milf) scenes. Several are oiled [massage](/category/massage) scenes from the [Nuru Massage](/channel/nuru-massage) channel, one is from [Adult Time](/channel/adult-time), and [Seth Gamble](/actor/seth-gamble) co-stars in one. [Big tits](/category/big-tits) and [brunette](/category/brunette) are the other common tags. Every video plays from its source site.', now()),
  ('sara-blonde', 'Sara Blonde videos on VEXN run from 19 to 82 minutes, and several tell a [cheating](/category/cheating) story with a [wife](/category/wife) at the centre. [MILF](/category/milf), [big tits](/category/big-tits), [big ass](/category/big-ass) and [brunette](/category/brunette) are the common tags. Every video plays from its source site.', now()),
  ('adriana-chechik', 'Adriana Chechik videos on VEXN are long, from 30 minutes to a 202-minute parody feature. [Lana Rhoades](/actor/lana-rhoades) co-stars in several of them and [Markus Dupree](/actor/markus-dupree) in three. Common tags are [anal](/category/anal), [threesome](/category/threesome), [group sex](/category/group-sex), [lesbian](/category/lesbian) and [squirt](/category/squirt), and one scene is from [Adult Time](/channel/adult-time). Every video plays from its source site.', now()),
  ('oliver-flynn', 'Oliver Flynn videos on VEXN are mostly short scenes of 11 to 13 minutes, plus a 30-minute scene with [Lena Paul](/actor/lena-paul) and one of 45 minutes. All are tagged [big tits](/category/big-tits), and [blonde](/category/blonde), [petite](/category/petite) and [anal](/category/anal) scenes are among them. One is from [Vixen](/channel/vixen), one from [Reality Kings](/channel/reality-kings), and [Blake Blossom](/actor/blake-blossom) co-stars in one. Every video plays from its source site.', now()),
  ('alina-lopez', 'Alina Lopez videos on VEXN run from 12 minutes to a 114-minute feature and are split between [Adult Time](/channel/adult-time), [Vixen](/channel/vixen) and the VEXN channel. [Kendra Sunderland](/actor/kendra-sunderland) co-stars in three, and [Angela White](/actor/angela-white) and [Seth Gamble](/actor/seth-gamble) in one each. Common tags are [threesome](/category/threesome), [group sex](/category/group-sex), [interracial](/category/interracial) and [big ass](/category/big-ass). Every video plays from its source site.', now()),
  ('jordi-jae', 'Jordi Jae videos on VEXN range from short studio scenes of about ten minutes to amateur scenes of close to an hour. Two are from [Brazzers](/channel/brazzers) and two from [Reality Kings](/channel/reality-kings), and [Angela White](/actor/angela-white) co-stars in one. [Big tits](/category/big-tits), [big dick](/category/big-dick) and [MILF](/category/milf) are the common tags. Every video plays from its source site.', now()),
  ('ricky-johnson', 'Ricky Johnson videos on VEXN run from 10 minutes to a 113-minute feature, and several are [Brazzers](/channel/brazzers) scenes. [Angela White](/actor/angela-white) co-stars in three and [Kendra Sunderland](/actor/kendra-sunderland) in one. Common tags are [big tits](/category/big-tits), [blonde](/category/blonde), [threesome](/category/threesome) and [hardcore](/category/hardcore). Every video plays from its source site.', now()),
  ('karla-kush', 'Karla Kush videos on VEXN run from 13 minutes to a 137-minute feature. Five are [lesbian](/category/lesbian) scenes with [Dani Daniels](/actor/dani-daniels), two of them from [New Sensations](/channel/new-sensations), and Riley Reid co-stars in two more; the rest include [anal](/category/anal) and [interracial](/category/interracial) scenes, and many include [masturbation](/category/masturbation). Every video plays from its source site.', now()),
  ('violet-myers', 'The Violet Myers videos on VEXN run 10 to 47 minutes: two are from [Brazzers](/channel/brazzers) and one from [Adult Time](/channel/adult-time), alongside scenes in the VEXN channel. Common tags are [big tits](/category/big-tits), [big ass](/category/big-ass) and [PAWG](/category/pawg), with a [massage](/category/massage) scene and a [sneaky sex](/category/sneaky-sex) scene among them. Every video plays from its source site.', now()),
  ('ellie-nova', 'Ellie Nova videos on VEXN are long, 30 to 64 minutes, and most are [massage](/category/massage) scenes, one of them from the [Nuru Massage](/channel/nuru-massage) channel. Two follow a [cheating](/category/cheating) story, and [big tits](/category/big-tits) and [brunette](/category/brunette) are other tags. Every video plays from its source site.', now())
